def draw(g):
    h,w=len(g),len(g[0]); o=[row[:] for row in g]
    marks=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (0,)]
    cells={}
    def add(p,v):
        cells.setdefault(p,[]).append(v)
    for r,c,v in marks:
        if v==1:
            add((r,c),1); add((r,c+1),5); add((r,c+2),5); add((r-1,c+2),1)
        elif v==2:
            for i in range(5): add((r,c-4+i), 2 if i in (0,4) else 5)
        elif v==3:
            for i in range(4): add((r+i,c), 3 if i in (0,3) else 5)
        elif v==6:
            for i in range(7): add((r-i,c), 6 if i in (0,6) else 5)
    for (r,c),vs in cells.items():
        if len(vs)>1: o[r][c]=4
        else:
            o[r][c]=vs[0]
    inter=[(r,c) for (r,c),vs in cells.items() if len(vs)>1]
    for r,c in inter:
        rr,cc=r+1,c-1
        while 0<=rr<h and 0<=cc<w:
            o[rr][cc]=4; rr+=1; cc-=1
    return o

